function baseData(){return {version:VERSION,profile:{name:'',greeting:'',university:'',campus:'',department:'',degree:'',batch:'',currentSemester:1,rollNo:'',advisor:'',expectedGraduation:''},settings:{theme:'obsidian',accent:'#78a9ff',clock24:false,showGreeting:true,weekStart:1,notifications:true,quietHours:true,quietStart:'23:00',quietEnd:'07:00',externalConfirm:false,autoUrl:true,customUrlRules:[],effects:{ambient:true,glass:true,motion:true,grid:true,cursor:true,ripple:true,particles:true}},semesters:[],courses:[],timetable:[],tasks:[],assessments:[],attendance:[],notes:[],resources:[],events:[],studySessions:[],goals:[],notifications:[],history:[],gradingProfiles:[defaultGradeProfile()],activeGradingProfile:'',tourDone:false};}
function defaultGradeProfile(){return {id:'gp-default',name:'4.00 GPA — Customizable',method:'absolute',rounding:2,scale:[['A',4],['A-',3.67],['B+',3.33],['B',3],['B-',2.67],['C+',2.33],['C',2],['C-',1.67],['D',1],['F',0]],bounds:[['A',90],['A-',85],['B+',80],['B',75],['B-',70],['C+',65],['C',60],['C-',55],['D',50],['F',0]],retake:'custom'};}
function mergeData(a,b){const d=deep(a); for(const k of Object.keys(d)){if(b&&b[k]!==undefined)d[k]=deep(b[k]);} d.version=VERSION; d.profile={...a.profile,...(d.profile||{})}; d.settings={...a.settings,...(d.settings||{})}; d.settings.effects={...a.settings.effects,...(d.settings.effects||{})}; for(const k of ['semesters','courses','timetable','tasks','assessments','attendance','notes','resources','events','studySessions','goals','notifications','history'])if(!Array.isArray(d[k]))d[k]=[]; if(!Array.isArray(d.gradingProfiles)||!d.gradingProfiles.length)d.gradingProfiles=[defaultGradeProfile()]; d.gradingProfiles=d.gradingProfiles.filter(g=>g&&typeof g==='object').map(g=>({...defaultGradeProfile(),...g,scale:Array.isArray(g.scale)?g.scale:[],bounds:Array.isArray(g.bounds)?g.bounds:[]})); if(!d.activeGradingProfile||!d.gradingProfiles.some(g=>g.id===d.activeGradingProfile))d.activeGradingProfile=d.gradingProfiles[0].id; return d;}
function deep(x){return JSON.parse(JSON.stringify(x));}
function uid(p){return p+'_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8);}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function val(id){return document.getElementById(id)?.value??''}
function today(d=new Date()){const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,10)}
function fmtDate(s){if(!s)return '—';const d=new Date(s+'T00:00:00');return d.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'});}
function fmtTime(t){if(!t)return '';let [h,m]=String(t).split(':').map(Number);if(state.settings.clock24)return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`;const ap=h>=12?'PM':'AM';h=h%12||12;return `${h}:${String(m).padStart(2,'0')} ${ap}`;}
function dynamicGreeting(){const h=new Date().getHours(); return h<12?'Good morning':h<18?'Good afternoon':'Good evening';}
