function loadState(){try{const raw=localStorage.getItem(KEY);if(raw)return mergeData(baseData(),JSON.parse(raw));}catch(e){console.warn(e)}return baseData();}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));queueNativeReminderSync();return true}catch(e){toast('Storage warning','Your browser could not save the latest data. Export a backup now.','err');return false}}
