function currentSemester(){const n=Number(state.profile.currentSemester||1);return state.semesters.find(s=>Number((s.name||'').match(/\d+/)?.[0]||0)===n)||state.semesters.find(s=>s.status==='active')||state.semesters[0]||null;}
function courseById(id){return state.courses.find(c=>c.id===id);}
function coursesForSem(semId){return state.courses.filter(c=>c.semesterId===semId);}
function courseGradePoints(c){if(c.gradePoint!==''&&c.gradePoint!==null&&c.gradePoint!==undefined){const n=Number(c.gradePoint);return Number.isFinite(n)?n:null}const gp=(state.gradingProfiles.find(g=>g.id===c.gradingProfileId)||state.gradingProfiles.find(g=>g.id===state.activeGradingProfile)||state.gradingProfiles[0]);if(!gp||!c.grade)return null;const row=gp.scale.find(r=>String(r[0]).toUpperCase()===String(c.grade).toUpperCase());return row?Number(row[1]):null;}
function semesterGPA(semId,officialOnly=false){const cs=coursesForSem(semId).filter(c=>c.countGpa!==false&&Number(c.credits)>0);if(!cs.length)return null;let q=0,cr=0;for(const c of cs){const gp=courseGradePoints(c);if(gp===null)return officialOnly?null:null;q+=gp*Number(c.credits);cr+=Number(c.credits)}return cr?q/cr:null;}
function cgpa(){const cs=state.courses.filter(c=>c.countCgpa!==false&&Number(c.credits)>0);let q=0,cr=0;for(const c of cs){const gp=courseGradePoints(c);if(gp===null)continue;q+=gp*Number(c.credits);cr+=Number(c.credits)}return cr?q/cr:null;}
function attendanceStats(courseId){const rs=state.attendance.filter(a=>a.courseId===courseId);const held=rs.filter(a=>!['cancelled','excused'].includes(a.status));const present=held.filter(a=>['present','late'].includes(a.status)).length;const late=held.filter(a=>a.status==='late').length;return {held:held.length,present,late,absent:held.filter(a=>a.status==='absent').length,percent:held.length?present/held.length*100:null};}
function weightedCourseScore(courseId){const ass=state.assessments.filter(a=>a.courseId===courseId&&!['dropped','excused'].includes(a.status));if(!ass.length)return null;let total=0,weight=0,missing=false;for(const a of ass){const w=Number(a.weight||0);if(w<0)continue;if(a.obtained===''||a.obtained===null||a.obtained===undefined||a.status==='pending'){missing=true;continue}const marks=Number(a.obtained),max=Number(a.max);if(!Number.isFinite(max)||max<=0||!Number.isFinite(marks))return null;if(marks<0||marks>max)return null;total+=(marks/max*100)*w;weight+=w;}if(weight<=0)return null;return {score:total/weight,weight,missing,complete:Math.abs(weight-100)<0.0001};}
function calcRequiredFinal(courseId,target){const ass=state.assessments.filter(a=>a.courseId===courseId&&!['dropped','excused'].includes(a.status));const pending=ass.filter(a=>a.obtained===''||a.obtained===null||a.obtained===undefined);if(pending.length!==1)return null;const p=pending[0],cur=ass.filter(a=>a!==p);let total=0,w=0;for(const a of cur){const ww=Number(a.weight||0);const marks=Number(a.obtained),max=Number(a.max);if(!ww||!max)return null;total+=(marks/max*100)*ww;w+=ww;}const pw=Number(p.weight||0);if(!pw)return null;const required=(target*(w+pw)-total)/pw;return required;}
