function startReminderEngine(){setInterval(()=>{const now=new Date();const d=today(now);const cur=now.getHours()*60+now.getMinutes();for(const c of state.timetable){if(Number(c.day)!==now.getDay())continue;if(c.startDate&&d<c.startDate)continue;if(c.endDate&&d>c.endDate)continue;const [h,m]=String(c.start||'00:00').split(':').map(Number);const mins=h*60+m-Number(c.reminder||0);if(Number(c.reminder)>0&&cur===mins){const key='r_'+c.id+'_'+d; if(localStorage.getItem(key))continue;localStorage.setItem(key,'1');const co=courseById(c.courseId);pushNotification(`${co?.name||'Class'} · Upcoming`,`${fmtTime(c.start)}–${fmtTime(c.end)}${c.room?' · '+c.room:''}${c.instructor?' · '+c.instructor:''}${c.type?' · '+c.type:''} · Starts in ${c.reminder} minutes`);}}},30000)}
function pushNotification(title,message){state.notifications.unshift({id:uid('n'),title,message,time:new Date().toISOString(),read:false});state.notifications=state.notifications.slice(0,120);persist();updateBadge();toast(title,message,'ok');if(state.settings.notifications&&window.MaoozAndroid){try{window.MaoozAndroid.postNotification(String(title),String(message));}catch(e){toast('Notification fallback','Native Android notification could not be posted; the in-app alert is still available.','warn')}}if(state.settings.notifications&&'Notification' in window&&Notification.permission==='granted'){try{new Notification('MaoozOS · '+title,{body:message})}catch{}}if('serviceWorker' in navigator&&navigator.serviceWorker.controller){navigator.serviceWorker.controller.postMessage({type:'SHOW_NOTIFICATION',title:String(title),message:String(message),url:'./index.html'});}}
