function requestNotifications(){if(window.MaoozAndroid){try{window.MaoozAndroid.requestNotifications();}catch(e){toast('Android notifications','Native permission request could not start; in-app reminders remain available.','warn')}}if(!('Notification' in window)){toast('Browser notifications unavailable','In-app reminders remain available.','warn');return;}try{Notification.requestPermission().then(p=>toast('Notifications',p==='granted'?'Browser notifications enabled.':'Permission not granted; in-app reminders remain available.',p==='granted'?'ok':'warn')).catch(()=>toast('Notification permission failed','In-app reminders remain available.','warn'));}catch(e){toast('Notification permission failed','In-app reminders remain available.','warn')}}
function androidAvailable(){return !!window.MaoozAndroid&&typeof window.MaoozAndroid.syncReminders==='function';}
let nativeReminderSyncTimer=0;
function queueNativeReminderSync(){if(!androidAvailable())return;clearTimeout(nativeReminderSyncTimer);nativeReminderSyncTimer=setTimeout(()=>{try{syncNativeReminders()}catch(e){toast('Reminder sync warning','MaoozOS could not refresh Android reminders. Your timetable is still saved.','warn');}},120);}
function nextOccurrenceForClass(c,now=new Date()){
  if(!c||c.day===undefined||!c.start)return null;
  const targetDay=Number(c.day); if(!Number.isInteger(targetDay)||targetDay<0||targetDay>6)return null;
  const startDate=c.startDate||''; const endDate=c.endDate||'';
  const base=new Date(now.getTime());
  base.setSeconds(0,0);
  for(let offset=0;offset<=370;offset++){
    const d=new Date(base.getTime()); d.setHours(0,0,0,0); d.setDate(d.getDate()+offset);
    const ds=today(d); if(startDate&&ds<startDate)continue; if(endDate&&ds>endDate)break; if(d.getDay()!==targetDay)continue;
    const [hh,mm]=String(c.start).split(':').map(Number); if(!Number.isFinite(hh)||!Number.isFinite(mm))continue;
    d.setHours(hh,mm,0,0);
    if(d.getTime()<=now.getTime())continue;
    return d;
  }
  return null;
}
function syncNativeReminders(){
  if(!androidAvailable())return true;
  try{
    if(state.settings.notifications===false){window.MaoozAndroid.syncReminders('[]');return true;}
    const now=Date.now(),jobs=[];
    for(const c of Array.isArray(state.timetable)?state.timetable:[]){
      const reminder=Math.max(0,Math.round(Number(c.reminder)||0)); if(reminder<=0)continue;
      const d=nextOccurrenceForClass(c,new Date(now)); if(!d)continue;
      const classAt=d.getTime(),fireAt=classAt-reminder*60000;
      if(fireAt<=now)continue;
      const co=courseById(c.courseId),endAt=c.endDate?new Date(c.endDate+'T23:59:59').getTime():0;
      const className=co?.name||'Class';
      jobs.push({id:String(c.id),classAt,fireAt,leadMinutes:reminder,periodMs:604800000,endAt,title:`${className} · Upcoming`,message:`${className} · ${fmtTime(c.start)}–${fmtTime(c.end)}${c.room?' · '+c.room:''}${c.instructor?' · '+c.instructor:''}${c.type?' · '+c.type:''} · Starts in ${reminder} minute${reminder===1?'':'s'}`,quietHours:!!state.settings.quietHours,quietStart:state.settings.quietStart,quietEnd:state.settings.quietEnd});
    }
    const result=window.MaoozAndroid.syncReminders(JSON.stringify(jobs));
    if(result===false)throw new Error('Android did not accept the reminder schedule.');
    return true;
  }catch(e){toast('Reminder sync warning',e?.message||'Android reminders could not be refreshed. Your timetable remains saved.','warn');return false;}
}
function syncAndroidReminders(){return syncNativeReminders();}
function refreshNotificationState(){
  try{
    const exact=window.MaoozAndroid&&typeof window.MaoozAndroid.canScheduleExactAlarms==='function'?window.MaoozAndroid.canScheduleExactAlarms():true;
    document.querySelectorAll('[data-exact-alarm-status]').forEach(el=>{el.textContent=exact?'Precise reminders available':'Android may deliver reminders later without Alarms & reminders access';});
  }catch(e){}
}

