function openSemesterModal(id=''){const s=id?state.semesters.find(x=>x.id===id):{name:'',academicYear:'',start:'',end:'',status:'upcoming',summaryOnly:false,finalized:false};modal(id?'Edit Semester':'Add Semester','Semester records can be detailed or historical summaries.',`<div class="form-grid"><div class="field"><label>Semester name</label><input id="f_sn" value="${esc(s.name)}" placeholder="Semester 1"></div><div class="field"><label>Academic year</label><input id="f_sy" value="${esc(s.academicYear)}" placeholder="2026–27"></div><div class="field"><label>Start</label><input id="f_ss" type="date" value="${esc(s.start)}"></div><div class="field"><label>End</label><input id="f_se" type="date" value="${esc(s.end)}"></div><div class="field"><label>Status</label><select id="f_st"><option value="upcoming" ${s.status==='upcoming'?'selected':''}>Upcoming</option><option value="active" ${s.status==='active'?'selected':''}>Active</option><option value="completed" ${s.status==='completed'?'selected':''}>Completed</option><option value="archived" ${s.status==='archived'?'selected':''}>Archived</option></select></div><div class="field"><label>History mode</label><select id="f_sum"><option value="detail" ${!s.summaryOnly?'selected':''}>Detailed</option><option value="summary" ${s.summaryOnly?'selected':''}>Historical summary</option></select></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveSemester('${id}')">Save</button>`)}
function saveSemester(id){const name=val('f_sn').trim(),start=val('f_ss'),end=val('f_se');if(!name)return userError('Semester name required','A semester needs a name so other records can reference it.','Enter something like Semester 1.');if(start&&end&&end<start)return userError('Invalid semester dates','The end date is before the start date.','Choose an end date on or after the start date.');let s=id?state.semesters.find(x=>x.id===id):{id:uid('sem'),finalized:false};Object.assign(s,{name,academicYear:val('f_sy').trim(),start,end,status:val('f_st'),summaryOnly:val('f_sum')==='summary'});if(!id)state.semesters.push(s);log(`${id?'Edited':'Created'} ${name}`);closeModal();refresh();toast('Semester saved','The semester record is stored locally.');}
