function saveCourse(id){const name=val('f_cn').trim(),credits=Number(val('f_cr'));if(!name)return userError('Course name required','The course must have a name so it can be identified everywhere.','Enter the course name.');if(!Number.isFinite(credits)||credits<=0)return userError('Credit hours invalid','GPA/CGPA needs a positive credit value.','Enter a value such as 1, 2, 3 or 4.');const sem=val('f_csem');let dup=state.courses.find(c=>c.id!==id&&c.semesterId===sem&&c.name.trim().toLowerCase()===name.toLowerCase());if(dup&&!confirm(`A similar course already exists: ${dup.name}. Create another record anyway?`))return;let c=id?courseById(id):{id:uid('course'),grade:'',gradePoint:'',countGpa:true,countCgpa:true,gradingProfileId:state.activeGradingProfile};Object.assign(c,{name,code:val('f_cc').trim(),credits,instructor:val('f_ci').trim(),section:val('f_cs').trim(),semesterId:sem,color:val('f_ccolor'),icon:val('f_cicon').trim()||'◈'});if(!id)state.courses.push(c);log(`${id?'Edited':'Created'} course: ${name}`);closeModal();refresh();toast('Course saved',`${name} is now linked to its semester.`);}
function openTaskModal(id=''){const t=id?state.tasks.find(x=>x.id===id):{title:'',courseId:currentCourseId()||'',type:'Assignment',dueDate:today(),dueTime:'23:59',priority:'normal',status:'not-started',description:'',tags:[]};modal(id?'Edit Task':'Add Task','Tasks are stored separately and shown on Dashboard and Calendar.',`<div class="form-grid"><div class="field full"><label>Title</label><input id="f_tt" value="${esc(t.title)}" placeholder="Complete PF Assignment 2"></div><div class="field"><label>Course</label><select id="f_tc"><option value="">Personal / none</option>${state.courses.map(c=>`<option value="${c.id}" ${c.id===t.courseId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Type</label><input id="f_ty" value="${esc(t.type||'Assignment')}" placeholder="Assignment"></div><div class="field"><label>Due date</label><input id="f_td" type="date" value="${esc(t.dueDate||today())}"></div><div class="field"><label>Due time</label><input id="f_tm" type="time" value="${esc(t.dueTime||'23:59')}"></div><div class="field"><label>Priority</label><select id="f_tp"><option ${t.priority==='low'?'selected':''}>low</option><option ${t.priority==='normal'?'selected':''}>normal</option><option ${t.priority==='high'?'selected':''}>high</option><option ${t.priority==='critical'?'selected':''}>critical</option></select></div><div class="field"><label>Status</label><select id="f_ts"><option value="not-started" ${t.status==='not-started'?'selected':''}>Not Started</option><option value="in-progress" ${t.status==='in-progress'?'selected':''}>In Progress</option><option value="completed" ${t.status==='completed'?'selected':''}>Completed</option><option value="on-hold" ${t.status==='on-hold'?'selected':''}>On Hold</option><option value="cancelled" ${t.status==='cancelled'?'selected':''}>Cancelled</option></select></div><div class="field full"><label>Description</label><textarea id="f_tdsc">${esc(t.description||'')}</textarea></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveTask('${id}')">Save Task</button>`)}
