function saveTask(id){const title=val('f_tt').trim(),due=val('f_td');if(!title)return userError('Task title required','The task needs a name for the planner.','Enter a clear title.');if(due&&Number.isNaN(new Date(due+'T00:00:00').getTime()))return userError('Invalid due date','The browser could not parse the selected date.','Choose a date using the date picker.');let t=id?state.tasks.find(x=>x.id===id):{id:uid('task'),createdAt:new Date().toISOString(),history:[]};if(!Array.isArray(t.history))t.history=[];t.history.push({time:new Date().toISOString(),status:val('f_ts'),dueDate:due});Object.assign(t,{title,courseId:val('f_tc'),type:val('f_ty').trim()||'Task',dueDate:due,dueTime:val('f_tm'),priority:val('f_tp'),status:val('f_ts'),description:val('f_tdsc')});if(!id)state.tasks.unshift(t);log(`${id?'Edited':'Created'} task: ${title}`);closeModal();refresh();toast('Task saved',t.status==='completed'?'Marked complete.':'Added to your planner.');}
