function saveAssessment(id){const name=val('f_an').trim(),max=Number(val('f_am')),obt=val('f_ao');if(!name)return userError('Assessment name required','The assessment needs a name.','Enter something like Quiz 1.');if(!Number.isFinite(max)||max<=0)return userError('Maximum marks invalid','Maximum marks must be positive.','Enter the actual maximum marks.');if(obt!==''&&(Number(obt)<0||Number(obt)>max))return userError('Marks are invalid',`Obtained marks must be between 0 and ${max}.`,'Use the configured maximum or enable a separate extra-credit rule.');const courseId=val('f_ac');if(!courseId)return userError('Course required','An assessment must belong to a course for academic calculations.','Add a course first.');let a=id?state.assessments.find(x=>x.id===id):{id:uid('assess'),history:[]};Object.assign(a,{name,type:val('f_at').trim()||'Assessment',courseId,date:val('f_ad'),max,obtained:obt===''?'':Number(obt),weight:Math.max(0,Number(val('f_aw'))||0),status:val('f_ast')});if(!id)state.assessments.unshift(a);const sum=state.assessments.filter(x=>x.courseId===courseId).reduce((n,x)=>n+(Number(x.weight)||0),0);if(sum>100.0001){toast('Assessment weights exceed 100%',`Current total for this course is ${sum.toFixed(2)}%. Review the weights before treating the course score as final.`,'warn');}log(`${id?'Edited':'Created'} assessment: ${name}`);closeModal();refresh();toast('Assessment saved','Raw marks and weight are stored locally.');}
function openAttendanceModal(id=''){const a=id?state.attendance.find(x=>x.id===id):{date:today(),courseId:currentCourseId(),status:'present',type:'Lecture',note:''};modal(id?'Edit Attendance':'Record Attendance','No record is never treated as absent.',`<div class="form-grid"><div class="field"><label>Date</label><input id="f_rd" type="date" value="${esc(a.date)}"></div><div class="field"><label>Course</label><select id="f_rc">${state.courses.map(c=>`<option value="${c.id}" ${c.id===a.courseId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Status</label><select id="f_rs"><option value="present">Present</option><option value="absent" ${a.status==='absent'?'selected':''}>Absent</option><option value="late" ${a.status==='late'?'selected':''}>Late</option><option value="excused" ${a.status==='excused'?'selected':''}>Excused</option><option value="cancelled" ${a.status==='cancelled'?'selected':''}>Cancelled</option></select></div><div class="field"><label>Type</label><input id="f_rt" value="${esc(a.type||'Lecture')}"></div><div class="field full"><label>Note</label><input id="f_rn" value="${esc(a.note||'')}" placeholder="Optional note"></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveAttendance('${id}')">Save</button>`)}
function saveAttendance(id){const date=val('f_rd'),courseId=val('f_rc'),status=val('f_rs');if(!date||!courseId)return userError('Attendance incomplete','Date and course are required for an attendance record.','Fill both fields.');const dup=state.attendance.find(a=>a.id!==id&&a.date===date&&a.courseId===courseId&&a.type===val('f_rt'));if(dup&&status!==dup.status&&!confirm('An attendance record already exists for this course/date/type. Edit it instead?'))return;let a=id?state.attendance.find(x=>x.id===id):{id:uid('att')};Object.assign(a,{date,courseId,status,type:val('f_rt').trim()||'Lecture',note:val('f_rn').trim()});if(!id)state.attendance.push(a);log(`${id?'Edited':'Recorded'} attendance`);closeModal();refresh();toast('Attendance saved',status==='present'?'Marked Present.':'Attendance record updated.');}
function openNoteModal(id=''){const n=id?state.notes.find(x=>x.id===id):{title:'',courseId:'',topic:'',content:'',tags:''};modal(id?'Edit Note':'Add Note','Notes save locally and can connect to courses and resources.',`<div class="form-grid"><div class="field full"><label>Title</label><input id="f_nt" value="${esc(n.title)}" placeholder="Pointers"></div><div class="field"><label>Course</label><select id="f_nc"><option value="">General</option>${state.courses.map(c=>`<option value="${c.id}" ${c.id===n.courseId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Topic</label><input id="f_ntopic" value="${esc(n.topic||'')}"></div><div class="field full"><label>Content</label><textarea id="f_nbody" placeholder="Write your notes…">${esc(n.content||'')}</textarea></div><div class="field full"><label>Tags</label><input id="f_ntags" value="${esc(n.tags||'')}" placeholder="#exam #important"></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveNote('${id}')">Save Note</button>`)}
function saveNote(id){const title=val('f_nt').trim(),content=val('f_nbody');if(!title&& !content)return userError('Note is empty','There is no title or content to save.','Add something first or cancel.');let n=id?state.notes.find(x=>x.id===id):{id:uid('note'),versions:[]};n.versions=n.versions||[];n.versions.unshift({time:new Date().toISOString(),title:n.title||'',content:n.content||''});n.versions=n.versions.slice(0,15);Object.assign(n,{title:title||'Untitled Note',courseId:val('f_nc'),topic:val('f_ntopic').trim(),content,tags:val('f_ntags').trim(),updatedAt:new Date().toISOString()});if(!id)state.notes.unshift(n);log(`${id?'Edited':'Created'} note: ${n.title}`);closeModal();refresh();toast('Note saved','Your note is stored locally.');}
function openResourceModal(id=''){const r=id?state.resources.find(x=>x.id===id):{url:'',name:'',type:'',icon:'',courseIds:[],tags:''};modal(id?'Edit Resource':'Add Resource','Paste a URL; known sites are recognized offline and every label is editable.',`<div class="form-grid"><div class="field full"><label>URL</label><input id="f_url" value="${esc(r.url||'')}" placeholder="https://github.com/…" oninput="previewUrl(this.value)"></div><div class="field"><label>Name</label><input id="f_un" value="${esc(r.name||'')}" placeholder="Auto from URL"></div><div class="field"><label>Type / subtype</label><input id="f_ut" value="${esc(r.type||'')}" placeholder="Video / Repository / Document"></div><div class="field"><label>Icon</label><input id="f_ui" value="${esc(r.icon||'')}" maxlength="4"></div><div class="field"><label>Tags</label><input id="f_ug" value="${esc(r.tags||'')}" placeholder="#important #coding"></div><div class="field full"><label>Course connections</label><select id="f_uc" multiple size="4">${state.courses.map(c=>`<option value="${c.id}" ${(r.courseIds||[]).includes(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field full"><div id="urlPreview" class="alert info">Paste a URL to preview its local recognition.</div></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveResource('${id}')">Save Resource</button>`);if(r.url)previewUrl(r.url)}
function recognizeURL(url){try{const u=new URL(url);const host=u.hostname.toLowerCase().replace(/^www\./,'');const custom=(state.settings.customUrlRules||[]).find(r=>host===r.domain||host.endsWith('.'+r.domain));if(custom)return {name:custom.name,type:custom.type||'Website',icon:custom.icon||'🌐'};const match=URL_RULES.find(r=>host===r[0]||host.endsWith('.'+r[0]));if(!match)return {name:host||'Website',type:'Website',icon:'🌐'};let type=match[2],name=match[1],icon=match[3];if(name==='YouTube'){if(u.pathname.includes('/playlist'))type='Playlist';else if(u.pathname.includes('/shorts'))type='Short';else if(u.pathname.includes('/channel')||u.pathname.includes('/@'))type='Channel';}else if(name==='GitHub'){if(u.pathname.split('/').filter(Boolean).length>=2)type='Repository';}else if(name==='Google Drive'){if(u.pathname.includes('/folders/'))type='Folder';}else if(name==='Google Docs'){if(u.pathname.includes('/spreadsheets/'))type='Spreadsheet';else if(u.pathname.includes('/presentation/'))type='Presentation';}return {name,type,icon};}catch{return null}}
function previewUrl(url){const el=document.getElementById('urlPreview');if(!el)return;const r=recognizeURL(url);el.innerHTML=r?`<div style="display:flex;align-items:center;gap:8px"><span style="font-size:18px">${esc(r.icon)}</span><div><strong>${esc(r.name)}</strong><div class="tiny muted">${esc(r.type)} · recognized locally without internet</div></div></div>`:`<div class="alert warn">This does not look like a standard web URL yet. The app will not invent a service label.</div>`;if(r){if(!val('f_un'))document.getElementById('f_un').value=r.name;if(!val('f_ut'))document.getElementById('f_ut').value=r.type;if(!val('f_ui'))document.getElementById('f_ui').value=r.icon}}
function saveResource(id){const url=val('f_url').trim();if(!/^https?:\/\//i.test(url))return userError('URL is not valid for this resource system','Only normal http:// and https:// web links are accepted.','Add the complete web address.');const rdet=recognizeURL(url),name=val('f_un').trim()||rdet?.name||new URL(url).hostname,type=val('f_ut').trim()||rdet?.type||'Website',icon=val('f_ui').trim()||rdet?.icon||'🌐';const selected=[...document.getElementById('f_uc').selectedOptions].map(o=>o.value);const dup=state.resources.find(x=>x.id!==id&&x.url===url);if(dup&&!confirm('The exact URL already exists. Create another entry anyway?'))return;let r=id?state.resources.find(x=>x.id===id):{id:uid('res'),createdAt:new Date().toISOString(),history:[]};Object.assign(r,{url,name,type,icon,tags:val('f_ug').trim(),courseIds:selected,updatedAt:new Date().toISOString()});if(!id)state.resources.unshift(r);log(`${id?'Edited':'Added'} resource: ${name}`);closeModal();refresh();toast('Resource saved',`${name} (${type}) is stored locally and remains editable.`);}
function openCustomRuleModal(){modal('Custom URL Rule','Teach MaoozOS about a domain you use frequently.',`<div class="form-grid"><div class="field"><label>Domain</label><input id="f_rd" placeholder="lms.example.edu"></div><div class="field"><label>Name</label><input id="f_rn2" placeholder="My University LMS"></div><div class="field"><label>Type</label><input id="f_rt2" placeholder="LMS"></div><div class="field"><label>Icon</label><input id="f_ri2" value="🎓" maxlength="4"></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveCustomRule()">Save Rule</button>`)}
function saveCustomRule(){const domain=val('f_rd').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/$/,'');const name=val('f_rn2').trim();if(!domain||!name)return userError('Rule incomplete','A domain and display name are required.','Fill both fields.');state.settings.customUrlRules=state.settings.customUrlRules||[];const idx=state.settings.customUrlRules.findIndex(r=>r.domain===domain);const item={domain,name,type:val('f_rt2').trim()||'Website',icon:val('f_ri2').trim()||'🌐'};if(idx>=0)state.settings.customUrlRules[idx]=item;else state.settings.customUrlRules.push(item);log('Updated custom URL rule: '+domain);closeModal();refresh();toast('URL rule saved','Future matching links can use your custom label and icon.');}
function openStudyModal(){modal('Study Session','This records actual study time and never alters planned time.',`<div class="form-grid"><div class="field"><label>Course</label><select id="f_sc"><option value="">General</option>${state.courses.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Topic</label><input id="f_stop" placeholder="Pointers"></div><div class="field"><label>Date</label><input id="f_sdate" type="date" value="${today()}"></div><div class="field"><label>Minutes</label><input id="f_smins" type="number" min="1" value="30"></div><div class="field full"><label>Notes</label><input id="f_snote" placeholder="Optional"></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveStudy()">Save Session</button>`)}
function saveStudy(){const mins=Number(val('f_smins'));if(!Number.isFinite(mins)||mins<=0)return userError('Study duration invalid','Actual study time must be positive.','Enter a duration greater than zero.');state.studySessions.unshift({id:uid('study'),courseId:val('f_sc'),topic:val('f_stop').trim(),date:val('f_sdate'),minutes:mins,note:val('f_snote').trim()});log('Recorded study session');closeModal();refresh();toast('Study saved',`${mins} minutes recorded.`);}
function openEventModal(){modal('Add Calendar Event','Personal events live in Calendar while academic items remain owned by their modules.',`<div class="form-grid"><div class="field full"><label>Title</label><input id="f_et" placeholder="Study group"></div><div class="field"><label>Date</label><input id="f_ed" type="date" value="${today()}"></div><div class="field"><label>Time</label><input id="f_etime" type="time"></div><div class="field full"><label>URL (optional)</label><input id="f_eurl" placeholder="https://…"></div><div class="field full"><label>Notes</label><textarea id="f_enote"></textarea></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveEvent()">Save Event</button>`)}
function saveEvent(){const title=val('f_et').trim(),date=val('f_ed');if(!title||!date)return userError('Event incomplete','A title and date are required.','Fill both fields.');state.events.push({id:uid('event'),title,date,time:val('f_etime'),url:val('f_eurl').trim(),notes:val('f_enote').trim()});log('Created event: '+title);closeModal();refresh();toast('Event saved','Your calendar event was added.');}
function openTimetableModal(id=''){const c=id?state.timetable.find(x=>x.id===id):{courseId:currentCourseId(),day:1,start:'10:00',end:'11:30',room:'',instructor:'',type:'Lecture',startDate:'',endDate:'',reminder:15};modal(id?'Edit Class':'Add Class','The timetable is the source for weekly classes, Dashboard class priority and reminders.',`<div class="form-grid"><div class="field full"><label>Course</label><select id="f_tc2">${state.courses.map(x=>`<option value="${x.id}" ${x.id===c.courseId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Day</label><select id="f_tday">${DAYS.map((d,i)=>`<option value="${i}" ${Number(c.day)===i?'selected':''}>${d}</option>`).join('')}</select></div><div class="field"><label>Type</label><input id="f_ttype" value="${esc(c.type||'Lecture')}"></div><div class="field"><label>Start</label><input id="f_tstart" type="time" value="${esc(c.start||'10:00')}"></div><div class="field"><label>End</label><input id="f_tend" type="time" value="${esc(c.end||'11:30')}"></div><div class="field"><label>Room</label><input id="f_troom" value="${esc(c.room||'')}"></div><div class="field"><label>Instructor</label><input id="f_tinst" value="${esc(c.instructor||'')}"></div><div class="field"><label>Repeat from</label><input id="f_tsdate" type="date" value="${esc(c.startDate||'')}"></div><div class="field"><label>Repeat until</label><input id="f_tedate" type="date" value="${esc(c.endDate||'')}"></div><div class="field"><label>Reminder minutes before</label><input id="f_trem" type="number" min="0" value="${Number(c.reminder||0)}"></div></div><div class="alert info" style="margin-top:10px">With dates filled, this class repeats every week between the two dates. This supports a complete weekly timetable for an entire month or semester. Leave dates blank for an open-ended weekly class.</div>`,`<button class="btn" onclick="closeModal()">Cancel</button>${id?`<button class="btn danger" onclick="deleteTimetable('${id}')">Delete</button>`:''}<button class="btn primary" onclick="saveTimetable('${id}')">Save Class</button>`)}
function deleteTimetable(id){const c=state.timetable.find(x=>x.id===id);if(!c)return;if(!confirm('Delete this timetable class? Its course, grades, attendance and other records will not be deleted.'))return;state.timetable=state.timetable.filter(x=>x.id!==id);log('Deleted timetable class');closeModal();refresh();toast('Class deleted','The class and its reminders were removed.','ok');}

function saveTimetable(id){const start=val('f_tstart'),end=val('f_tend'),courseId=val('f_tc2'),day=Number(val('f_tday'));if(!courseId)return userError('Course required','A class needs a course connection.','Create a course first.');if(!start||!end)return userError('Class time incomplete','Both start and end times are needed.','Choose both times.');if(end<=start)return userError('Invalid class time','The end time must be after the start time.','Correct the time range.');const sd=val('f_tsdate'),ed=val('f_tedate');if(sd&&ed&&ed<sd)return userError('Invalid class dates','The end date is before the start date.','Correct the date range.');const duplicate=state.timetable.find(x=>x.id!==id&&x.courseId===courseId&&Number(x.day)===day&&x.start===start&&x.end===end&&x.startDate===sd&&x.endDate===ed);if(duplicate&&!confirm('A matching class already exists. Add another anyway?'))return;let c=id?state.timetable.find(x=>x.id===id):{id:uid('class')};Object.assign(c,{courseId,day,start,end,room:val('f_troom').trim(),instructor:val('f_tinst').trim(),type:val('f_ttype').trim()||'Lecture',startDate:sd,endDate:ed,reminder:Math.max(0,Number(val('f_trem'))||0)});if(!id)state.timetable.push(c);log(`${id?'Edited':'Created'} timetable class`);closeModal();refresh();toast('Class saved','Timetable, Dashboard and reminders now use this class.');}
function openGradingProfileModal(id=''){const g=id?state.gradingProfiles.find(x=>x.id===id):defaultGradeProfile();if(!g)return userError('Grading profile not found','The selected grading profile no longer exists.','Choose another profile.');const rows=(g.scale||[]).map((r,i)=>`<div class="grid g4 grade-row" id="gradeRow_${i}"><div class="field"><label>Grade letter</label><input class="gp-letter" value="${esc(r[0])}" placeholder="A+"></div><div class="field"><label>Grade point</label><input class="gp-point" type="number" step="0.01" value="${Number(r[1])}"></div><div class="field"><label>Minimum %</label><input class="gp-bound" type="number" min="0" max="100" step="0.01" value="${Number((g.bounds||[]).find(b=>String(b[0]).toUpperCase()===String(r[0]).toUpperCase())?.[1]??0)}"></div><div class="field" style="display:flex;align-items:end"><button class="btn small danger" type="button" onclick="this.closest('.grade-row').remove()">Remove</button></div></div>`).join('');modal(id?'Edit Grading Profile':'New Grading Profile','Build exactly the grade letters and points your university/course uses. A+, D+, D−, custom letters and any numeric grade points are supported.',`<div class="form-grid"><div class="field full"><label>Profile name</label><input id="f_gname" value="${esc(g.name||'')}" placeholder="My University Grading System"></div><div class="field"><label>Method</label><select id="f_gmethod"><option value="absolute" ${g.method==='absolute'?'selected':''}>Absolute</option><option value="relative" ${g.method==='relative'?'selected':''}>Relative</option><option value="pass/fail" ${g.method==='pass/fail'?'selected':''}>Pass / Fail</option><option value="custom" ${g.method==='custom'?'selected':''}>Custom</option></select></div><div class="field"><label>Rounding decimals</label><input id="f_ground" type="number" min="0" max="8" value="${Number(g.rounding??2)}"></div><div class="field full"><label>Quick preset (optional)</label><select onchange="applyGradePreset(this.value)"><option value="">Keep current scale</option><option value="plusminus4">4.00 Plus/Minus</option><option value="fourPoint3">4.30 Plus/Minus</option><option value="passfail">Pass / Fail</option><option value="lettersOnly">Custom Letter Starter</option></select></div></div><div class="split" style="margin-top:14px"><div class="section-title">Grade letters & points</div><button class="btn small" type="button" onclick="addGradeScaleRow()">＋ Add grade</button></div><div id="gradeScaleRows" style="margin-top:8px;max-height:340px;overflow:auto">${rows||''}</div><div class="form-help" style="margin-top:10px">Grade letters are fully customizable. Add A+, A, A−, B+, B, D+, D−, F, P, U, or your own labels. Grade points and minimum percentage boundaries can both be edited.</div>` ,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveGradingProfile('${id}')">Save Profile</button>`);}
function applyGradePreset(kind){const wrap=document.getElementById('gradeScaleRows');if(!wrap||!kind)return;const presets={plusminus4:[['A+',4.00,90],['A',4.00,85],['A-',3.67,80],['B+',3.33,75],['B',3.00,70],['B-',2.67,65],['C+',2.33,60],['C',2.00,55],['C-',1.67,50],['D+',1.33,45],['D',1.00,40],['D-',0.67,35],['F',0.00,0]],fourPoint3:[['A+',4.30,90],['A',4.00,85],['A-',3.70,80],['B+',3.30,75],['B',3.00,70],['B-',2.70,65],['C+',2.30,60],['C',2.00,55],['C-',1.70,50],['D+',1.30,45],['D',1.00,40],['D-',0.70,35],['F',0.00,0]],passfail:[['P',1.00,50],['F',0.00,0]],lettersOnly:[['A+',4.00,90],['A',4.00,85],['A-',3.67,80],['B+',3.33,75],['B',3.00,70],['B-',2.67,65],['C+',2.33,60],['C',2.00,55],['C-',1.67,50],['D+',1.33,45],['D',1.00,40],['D-',0.67,35],['F',0.00,0]]};const rows=presets[kind];if(!rows)return;wrap.innerHTML=rows.map((r,i)=>`<div class="grid g4 grade-row"><div class="field"><label>Grade letter</label><input class="gp-letter" value="${esc(r[0])}"></div><div class="field"><label>Grade point</label><input class="gp-point" type="number" step="0.01" value="${r[1]}"></div><div class="field"><label>Minimum %</label><input class="gp-bound" type="number" min="0" max="100" step="0.01" value="${r[2]}"></div><div class="field" style="display:flex;align-items:end"><button class="btn small danger" type="button" onclick="this.closest('.grade-row').remove()">Remove</button></div></div>`).join('');} 
function addGradeScaleRow(letter='',point=''){const wrap=document.getElementById('gradeScaleRows');if(!wrap)return;const i=wrap.querySelectorAll('.grade-row').length;const row=document.createElement('div');row.className='grid g4 grade-row';row.innerHTML=`<div class="field"><label>Grade letter</label><input class="gp-letter" value="${esc(letter)}" placeholder="A+"></div><div class="field"><label>Grade point</label><input class="gp-point" type="number" step="0.01" value="${point!==''?Number(point):''}" placeholder="4.00"></div><div class="field"><label>Minimum %</label><input class="gp-bound" type="number" min="0" max="100" step="0.01" value="0"></div><div class="field" style="display:flex;align-items:end"><button class="btn small danger" type="button" onclick="this.closest('.grade-row').remove()">Remove</button></div>`;wrap.appendChild(row);}
function saveGradingProfile(id=''){const name=val('f_gname').trim();if(!name)return userError('Profile name required','A grading profile needs a clear name.','Enter a name.');const rows=[...document.querySelectorAll('#gradeScaleRows .grade-row')].map(row=>{const letter=row.querySelector('.gp-letter')?.value.trim();const point=Number(row.querySelector('.gp-point')?.value);const bound=Number(row.querySelector('.gp-bound')?.value);return {letter,point,bound};});if(!rows.length)return userError('Grade scale is empty','At least one grade letter and grade point are required.','Add a grade such as A = 4.00.');const clean=[];const seen=new Set();for(const r of rows){if(!r.letter||!Number.isFinite(r.point)||!Number.isFinite(r.bound)||r.bound<0||r.bound>100)return userError('Grade scale has an invalid row','Every grade needs a label, numeric grade point and a minimum percentage from 0 to 100.','Fix or remove the highlighted row.');const key=r.letter.toUpperCase();if(seen.has(key))return userError('Duplicate grade letter',`The grade ${r.letter} appears more than once.`,'Keep each grade letter unique.');seen.add(key);clean.push([r.letter,r.point,r.bound]);}let g=id?state.gradingProfiles.find(x=>x.id===id):null;if(!g){g=defaultGradeProfile();g.id=uid('gp');state.gradingProfiles.push(g);}g.name=name;g.method=val('f_gmethod');g.rounding=Math.max(0,Math.min(8,Number(val('f_ground'))||0));g.scale=clean.map(r=>[r[0],r[1]]);g.bounds=clean.map(r=>[r[0],r[2]]);state.activeGradingProfile=g.id;for(const c of state.courses){if(!c.gradingProfileId)c.gradingProfileId=g.id;}log(`${id?'Edited':'Created'} grading profile: ${name}`);closeModal();refresh();toast('Grading profile saved','Your custom grade letters and points are now active.');}
function deleteGradingProfile(id){if(state.gradingProfiles.length<=1)return userError('Cannot delete the last grading profile','MaoozOS needs at least one grading profile.','Create another profile first.');const used=state.courses.filter(c=>c.gradingProfileId===id).length;if(used&& !confirm(`This profile is used by ${used} course(s). Deleting it will move those courses to the default active profile. Continue?`))return;state.gradingProfiles=state.gradingProfiles.filter(g=>g.id!==id);const fallback=state.gradingProfiles[0].id;state.courses.forEach(c=>{if(c.gradingProfileId===id)c.gradingProfileId=fallback;});if(state.activeGradingProfile===id)state.activeGradingProfile=fallback;persist();refresh();toast('Grading profile deleted','Affected courses were reassigned without deleting their grades.');}
function saveGrade(courseId){const grade=val('grade_'+courseId).trim(),gp=val('gp_'+courseId);const c=courseById(courseId);if(!c)return;const profile=state.gradingProfiles.find(g=>g.id===c.gradingProfileId)||state.gradingProfiles.find(g=>g.id===state.activeGradingProfile);if(grade&&!Number.isFinite(Number(gp))&&profile?.method==='absolute'){const mapped=profile.scale.find(r=>String(r[0]).toUpperCase()===grade.toUpperCase());if(mapped)c.gradePoint=Number(mapped[1]);else return userError('Unknown grade','The entered grade does not exist in the selected scale.','Choose a configured grade or edit the grading profile.');}else c.gradePoint=gp===''?'':Number(gp);c.grade=grade;c.gradingProfileId=profile?.id||state.activeGradingProfile;c.lastGradeChange=new Date().toISOString();log('Updated grade: '+c.name);refresh();toast('Grade saved','The authoritative GPA engine will use this grade and credit value.');}
function finalizeSemester(id){const s=state.semesters.find(x=>x.id===id);if(!s)return;const g=semesterGPA(id);if(g===null)return userError('Semester cannot be finalized','One or more GPA-counted courses do not have valid grade points.','Enter official grades or explicitly exclude the courses from GPA.');const cr=coursesForSem(id).reduce((n,c)=>n+(Number(c.credits)||0),0);s.finalized=true;s.status='completed';s.snapshot={gpa:g,credits:cr,gradingProfileIds:coursesForSem(id).map(c=>c.gradingProfileId||state.activeGradingProfile),date:new Date().toISOString()};log('Finalized '+s.name);refresh();toast('Semester finalized','A historical snapshot was saved.');}
function reopenSemester(id){const s=state.semesters.find(x=>x.id===id);if(!s)return;s.finalized=false;s.status='active';s.snapshot=null;log('Reopened '+s.name);refresh();toast('Semester reopened','Historical editing is available again.');}
function openSemesterDetails(id){const s=state.semesters.find(x=>x.id===id);if(!s)return;const cs=coursesForSem(id),g=semesterGPA(id);modal(s.name,'Semester overview, grades and protections.',`<div class="stat-grid"><div class="card stat"><div class="stat-label">GPA</div><div class="stat-value">${g==null?'—':g.toFixed(2)}</div></div><div class="card stat"><div class="stat-label">Credits</div><div class="stat-value">${cs.reduce((n,c)=>n+Number(c.credits||0),0)}</div></div><div class="card stat"><div class="stat-label">Courses</div><div class="stat-value">${cs.length}</div></div><div class="card stat"><div class="stat-label">Status</div><div class="stat-value" style="font-size:18px">${esc(s.status)}</div></div></div><div class="section-head"><div class="section-title">Courses</div>${btn('＋ Add Course',`closeModal();openCourseModal('','${id}')`,'btn small')}</div><div class="list">${cs.length?cs.map(c=>`<div class="item"><div class="item-left"><div class="item-icon" style="background:${esc(c.color||state.settings.accent)}22">${esc(c.icon||'◈')}</div><div class="item-main"><div class="item-title">${esc(c.name)}</div><div class="item-sub">${esc(c.code||'')} · ${Number(c.credits)} credits · Grade ${esc(c.grade||'—')}</div></div></div><div class="item-right">${btn('Edit',`closeModal();openCourseModal('${c.id}')`,'btn small')}</div></div>`).join(''):`<div class="empty"><h4>No courses yet</h4><p>Add courses to build this semester.</p></div>`}</div>`,`${s.finalized?btn('Reopen','reopenSemester(\''+s.id+'\');closeModal()','btn'):btn('Finalize Semester','finalizeSemester(\''+s.id+'\');closeModal()','btn primary')}<button class="btn" onclick="closeModal()">Close</button>`)}
function renderDashboard(){const p=state.profile,sem=currentSemester(),classes=classesToday(),tasks=state.tasks.filter(t=>t.status!=='completed'&&t.status!=='cancelled'&&t.dueDate).sort((a,b)=>(a.dueDate+a.dueTime).localeCompare(b.dueDate+b.dueTime)),todayTasks=tasks.filter(t=>t.dueDate===today()),assToday=state.assessments.filter(a=>a.date===today()),now=new Date(),next=nextClass();const g=sem?semesterGPA(sem.id):null,cg=cgpa(),study=state.studySessions.reduce((n,s)=>n+Number(s.minutes||0),0);return pageHead('Command Center','Dashboard',`${state.settings.showGreeting===false?'':esc(p.greeting||dynamicGreeting())+' · '}${p.name||'Student'} · <span id="liveClock">${new Date().toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',hour12:!state.settings.clock24})}</span>`,btn('＋ Quick Add','quickAdd()','btn primary'))+`<div class="card hero hover"><div><div class="hero-kicker"><span class="pulse"></span>${esc(sem?.name||'Set up your first semester')}</div><div class="hero-name">${esc(p.name||'Welcome to MaoozOS')}</div><div class="hero-meta">${esc(p.university||'Your university')} ${p.campus?'· '+esc(p.campus):''} ${p.degree?'· '+esc(p.degree):''}<br>${sem?esc(sem.name):'Add a semester to start your academic workspace.'}</div><div class="hero-actions">${btn('＋ Class','openTimetableModal()','btn primary')}${btn('＋ Deadline','openTaskModal()','btn soft')}${btn('＋ URL','openResourceModal()','btn soft')}${btn('Start Tour','startTour(true)','btn')}${btn('Settings','showPage(\'settings\')','btn')}</div></div><div class="hero-side"><div class="orb"><span>MAOOZOS<br>LOCAL • PRIVATE</span></div></div></div><div class="section-head"><div class="section-title">Priority now</div><div class="section-note">Most important first</div></div><div class="priority-grid"><div class="card priority-card hover"><div class="split"><div><div class="eyebrow">Today's Classes</div><div class="priority-big" style="margin-top:7px">${classes.length}</div><div class="muted tiny">All scheduled classes for today</div></div>${next?`<span class="pill success">NEXT ${fmtTime(next.start)}</span>`:`<span class="pill">No class next</span>`}</div><div class="list" style="margin-top:13px">${classes.length?classes.slice(0,5).map(c=>classRow(c)).join(''):`<div class="empty"><h4>No classes today</h4><p>Your timetable is clear. Add a class from Timetable.</p></div>`}</div></div><div class="card priority-card hover"><div class="split"><div><div class="eyebrow">Deadlines & Assessments</div><div class="priority-big" style="margin-top:7px">${todayTasks.length+assToday.length}</div><div class="muted tiny">Due today</div></div><span class="pill ${todayTasks.length+assToday.length?'danger':''}">${todayTasks.length+assToday.length?'ATTENTION':'CLEAR'}</span></div><div class="list" style="margin-top:13px">${[...todayTasks.slice(0,3).map(t=>`<div class="item"><div class="item-left"><div class="item-icon">✓</div><div class="item-main"><div class="item-title">${esc(t.title)}</div><div class="item-sub">${esc(t.type)} · ${esc(t.dueTime||'today')}</div></div></div><span class="pill ${t.priority==='high'||t.priority==='critical'?'danger':'warn'}">${esc(t.priority)}</span></div>`),...assToday.slice(0,3).map(a=>`<div class="item"><div class="item-left"><div class="item-icon">⌁</div><div class="item-main"><div class="item-title">${esc(a.name)}</div><div class="item-sub">${esc(courseById(a.courseId)?.name||'Course')} · ${esc(a.type)}</div></div></div><span class="pill danger">Today</span></div>`)].join('')||`<div class="empty"><h4>No deadlines today</h4><p>Your top priority area is clear.</p></div>`}</div></div></div><div class="section-head"><div class="section-title">Next up</div><div class="section-note">Classes and deadlines first</div></div><div class="grid g3"><div class="card hover"><div class="eyebrow">Next class</div>${next?`<div class="metric" style="margin-top:8px">${esc(courseById(next.courseId)?.name||'Class')}</div><div class="muted tiny">${fmtTime(next.start)}–${fmtTime(next.end)} · ${esc(next.room||'Room not set')}</div>`:`<div class="muted" style="margin-top:10px">No upcoming class in the current timetable.</div>`}</div><div class="card hover"><div class="eyebrow">Current semester GPA</div><div class="metric" style="margin-top:8px">${g==null?'—':g.toFixed(2)}</div><div class="muted tiny">Only valid configured grades and credits are used.</div></div><div class="card hover"><div class="eyebrow">Overall CGPA</div><div class="metric" style="margin-top:8px">${cg==null?'—':cg.toFixed(2)}</div><div class="muted tiny">Historical and current completed grade records.</div></div></div><div class="section-head"><div class="section-title">Secondary overview</div><div class="section-note">Useful, lower priority</div></div><div class="stat-grid"><div class="card stat hover"><div class="stat-label">Open tasks</div><div class="stat-value">${tasks.length}</div><div class="stat-foot">Incomplete planner items</div></div><div class="card stat hover"><div class="stat-label">Courses</div><div class="stat-value">${state.courses.length}</div><div class="stat-foot">Across all semesters</div></div><div class="card stat hover"><div class="stat-label">Study logged</div><div class="stat-value">${(study/60).toFixed(1)}h</div><div class="stat-foot">All recorded sessions</div></div><div class="card stat hover"><div class="stat-label">Resources</div><div class="stat-value">${state.resources.length}</div><div class="stat-foot">URLs saved locally</div></div></div>`}
function classStatus(c, now=new Date()){const d=new Date(now);const day=Number(c.day);if(!Number.isFinite(day)||day<0||day>6)return 'upcoming';const todayStr=today(d);if(c.startDate&&todayStr<c.startDate)return 'upcoming';if(c.endDate&&todayStr>c.endDate)return 'completed';if(day!==d.getDay())return 'upcoming';const [sh,sm]=String(c.start||'00:00').split(':').map(Number);const [eh,em]=String(c.end||'00:00').split(':').map(Number);const startMin=(Number(sh)||0)*60+(Number(sm)||0);const endMin=(Number(eh)||0)*60+(Number(em)||0);const nowMin=d.getHours()*60+d.getMinutes();if(endMin<=startMin)return 'upcoming';if(nowMin<startMin)return 'upcoming';if(nowMin>=endMin)return 'completed';return 'current';}
function classRow(c){const co=courseById(c.courseId),now=new Date(),st=classStatus(c,now);const badge=st==='current'?'<span class="pill success">NOW</span>':st==='completed'?'<span class="pill">DONE</span>':nextClass()?.id===c.id?'<span class="pill success">NEXT</span>':'<span class="pill">UPCOMING</span>';return `<div class="item clickable" onclick="openTimetableModal('${c.id}')"><div class="item-left"><div class="item-icon" style="background:${esc(co?.color||state.settings.accent)}22">${esc(co?.icon||'◈')}</div><div class="item-main"><div class="item-title">${esc(co?.name||'Class')}</div><div class="item-sub">${fmtTime(c.start)}–${fmtTime(c.end)} · ${esc(c.room||'Room not set')} · ${esc(c.instructor||'Instructor not set')} · ${esc(c.type||'Lecture')}</div></div></div><div class="item-right">${badge}</div></div>`}
function classesToday(){const d=new Date().getDay(),day=today();return state.timetable.filter(c=>Number(c.day)===d&&(!c.startDate||day>=c.startDate)&&(!c.endDate||day<=c.endDate)).sort((a,b)=>a.start.localeCompare(b.start));}
function nextClass(){const now=new Date();const candidates=[];for(const c of state.timetable){const d=nextOccurrenceForClass(c,now);if(d)candidates.push({c,time:d.getTime()});}candidates.sort((a,b)=>a.time-b.time||String(a.c.start).localeCompare(String(b.c.start)));return candidates[0]?.c||null;}
function renderAcademic(){const p=state.profile,sem=currentSemester(),gp=state.gradingProfiles.find(g=>g.id===state.activeGradingProfile);const profiles=state.gradingProfiles.map(g=>`<div class="item"><div class="item-left"><div class="item-icon">∑</div><div class="item-main"><div class="item-title">${esc(g.name)}</div><div class="item-sub">${esc(g.method)} · ${Number(g.scale?.length||0)} grades · ${Number(g.rounding??2)} decimals</div></div></div><div class="item-right">${g.id===state.activeGradingProfile?'<span class="pill success">ACTIVE</span>':btn('Use',`state.activeGradingProfile='${g.id}';persist();refresh()`,'btn small')}${btn('Edit',`openGradingProfileModal('${g.id}')`,'btn small')}${g.id!=='gp-default'?btn('Delete',`deleteGradingProfile('${g.id}')`,'btn small danger'):''}</div></div>`).join('');return pageHead('Foundation','Academic Profile','Identity, university and configurable academic rules used across MaoozOS.',btn('Edit Profile','openAcademicModal()','btn primary'))+`<div class="grid g3"><div class="card hover"><div class="eyebrow">Student</div><div class="metric" style="margin-top:9px">${esc(p.name||'Not set')}</div><div class="muted tiny">${esc(p.rollNo||'Roll number not set')}</div></div><div class="card hover"><div class="eyebrow">University</div><div class="metric" style="margin-top:9px;font-size:20px">${esc(p.university||'Not set')}</div><div class="muted tiny">${esc(p.campus||'Campus not set')} · ${esc(p.degree||'Degree not set')}</div></div><div class="card hover"><div class="eyebrow">Current semester</div><div class="metric" style="margin-top:9px">${esc(sem?.name||'Not set')}</div><div class="muted tiny">${esc(gp?.name||'No grading profile')}</div></div></div><div class="section-head"><div class="section-title">Grading profiles</div>${btn('＋ New Profile','openGradingProfileModal()','btn small primary')}</div><div class="card"><div class="list">${profiles||`<div class="empty"><h4>No grading profiles</h4></div>`}</div></div><div class="section-head"><div class="section-title">Active grade scale</div><div class="section-note">Fully editable · custom letters supported</div></div><div class="card"><div class="chip-row" style="margin-top:4px">${(gp?.scale||[]).map(r=>`<span class="chip">${esc(r[0])} = ${Number(r[1]).toFixed(2)}</span>`).join('')}</div>${gp?`<div class="row-actions" style="margin-top:12px">${btn('Edit active grading profile',`openGradingProfileModal('${gp.id}')`,'btn small')}</div>`:''}</div><div class="section-head"><div class="section-title">University links</div>${btn('＋ Add URL','openResourceModal()','btn small')}</div><div class="card"><div class="list">${state.resources.filter(r=>!r.courseIds?.length).slice(0,8).map(resourceRow).join('')||`<div class="empty"><h4>No global university links</h4><p>Add your portal, LMS, timetable and other important URLs.</p></div>`}</div></div>`}
function renderSemesters(){const rows=state.semesters.map(s=>{const g=semesterGPA(s.id),cs=coursesForSem(s.id);return `<div class="item"><div class="item-left"><div class="item-icon">▤</div><div class="item-main"><div class="item-title">${esc(s.name)} ${s.finalized?'🔒':''}</div><div class="item-sub">${esc(s.academicYear||'Academic year not set')} · ${cs.length} courses · ${cs.reduce((n,c)=>n+Number(c.credits||0),0)} credits</div></div></div><div class="item-right"><span class="pill">GPA ${g==null?'—':g.toFixed(2)}</span>${btn('Open',`openSemesterDetails('${s.id}')`,'btn small')}${btn('Edit',`openSemesterModal('${s.id}')`,'btn small')}</div></div>`}).join('');return pageHead('Academic','Semesters','Your complete semester history, summaries, snapshots and protected final records.',btn('＋ Semester','openSemesterModal()','btn primary'))+`<div class="card"><div class="list">${rows||`<div class="empty"><h4>No semesters yet</h4><p>Create Semester 1 or import a historical semester summary.</p></div>`}</div></div>`}
function renderCourses(){const grouped=state.semesters.map(s=>{const cs=coursesForSem(s.id);return `<div class="section-head"><div><div class="section-title">${esc(s.name)}</div><div class="section-note">${cs.length} courses</div></div>${btn('＋ Add Course',`openCourseModal('','${s.id}')`,'btn small')}</div><div class="grid g3">${cs.map(c=>`<div class="card hover clickable" onclick="openCourseModal('${c.id}')"><div class="split"><div class="item-icon" style="background:${esc(c.color||state.settings.accent)}22">${esc(c.icon||'◈')}</div><span class="pill">${Number(c.credits)} cr</span></div><div class="item-title" style="font-size:14px;margin-top:12px">${esc(c.name)}</div><div class="item-sub">${esc(c.code||'No code')} · ${esc(c.section||'No section')} · ${esc(c.instructor||'Instructor not set')}</div><div class="split" style="margin-top:13px"><span class="pill">Grade ${esc(c.grade||'—')}</span><span class="pill">Att ${attendanceStats(c.id).percent==null?'—':attendanceStats(c.id).percent.toFixed(1)+'%'}</span></div></div>`).join('')||`<div class="empty"><h4>No courses</h4><p>Add your courses to this semester.</p></div>`}</div>`}).join('');return pageHead('Academic','Courses','Every course is a hub connected to grades, attendance, tasks, notes, resources and timetable.',btn('＋ Course','openCourseModal()','btn primary'))+grouped}
function renderTimetable(){const headers=[...Array(7)].map((_,i)=>{const di=(state.settings.weekStart+i)%7;return `<div class="week-cell week-head ${di===new Date().getDay()?'today-col':''}">${DAY_SHORT[di]}</div>`}).join('');const times=[];for(let h=7;h<=22;h++)times.push(`${String(h).padStart(2,'0')}:00`);let cells=`<div class="week-cell week-head">Time</div>${headers}`;for(const t of times){cells+=`<div class="week-cell time-col">${fmtTime(t)}</div>`;for(let i=0;i<7;i++){const di=(state.settings.weekStart+i)%7;const items=state.timetable.filter(c=>Number(c.day)===di&&c.start.slice(0,2)===t.slice(0,2));cells+=`<div class="week-cell ${di===new Date().getDay()?'today-col':''}">${items.map(c=>`<div class="class-chip" onclick="openTimetableModal('${c.id}')"><strong>${esc(courseById(c.courseId)?.name||'Class')}</strong><small>${fmtTime(c.start)}–${fmtTime(c.end)} · ${esc(c.room||'')}</small></div>`).join('')}</div>`}}const all=state.timetable.slice().sort((a,b)=>Number(a.day)-Number(b.day)||a.start.localeCompare(b.start));return pageHead('Schedule','Timetable','Ultra-final class schedule: one class record drives the weekly view, Dashboard priority and reminders.',btn('＋ Add Class','openTimetableModal()','btn primary'))+`<div class="grid g3"><div class="card hover"><div class="eyebrow">Today</div><div class="metric" style="margin-top:8px">${classesToday().length}</div><div class="muted tiny">Classes scheduled</div></div><div class="card hover"><div class="eyebrow">Next</div><div class="metric" style="font-size:20px;margin-top:8px">${nextClass()?esc(courseById(nextClass().courseId)?.name||'Class'):'—'}</div><div class="muted tiny">${nextClass()?fmtTime(nextClass().start)+' · '+DAY_SHORT[Number(nextClass().day)]:'No upcoming class'}</div></div><div class="card hover"><div class="eyebrow">Timetable URL</div><div class="item-sub" style="margin-top:10px">${state.resources.find(r=>/timetable|schedule/i.test(r.name))?resourceRow(state.resources.find(r=>/timetable|schedule/i.test(r.name))):'Add your university timetable URL from Resources.'}</div></div></div><div class="section-head"><div class="section-title">Weekly schedule</div><div class="section-note">Click a class to edit it</div></div><div class="week"><div class="week-grid">${cells}</div></div><div class="section-head"><div class="section-title">All class records</div><div class="section-note">Edit or delete any class · weekly rules repeat through the selected date range</div></div><div class="card"><div class="list">${all.map(c=>`<div class="item" onclick="openTimetableModal('${c.id}')"><div class="item-left"><div class="item-icon">🗓</div><div class="item-main"><div class="item-title">${esc(courseById(c.courseId)?.name||'Class')}</div><div class="item-sub">${DAY_SHORT[Number(c.day)]} · ${fmtTime(c.start)}–${fmtTime(c.end)} · ${esc(c.room||'Room not set')} · ${esc(c.type||'Lecture')}</div></div></div><div class="item-right"><span class="pill">${classStatus(c)==='current'?'NOW':classStatus(c)==='completed'?'DONE':nextClass()?.id===c.id?'NEXT':'UPCOMING'}</span>${btn('Edit',`openTimetableModal('${c.id}')`,'btn small')}</div></div>`).join('')||`<div class="empty"><h4>No classes</h4><p>Add your first class to build the schedule.</p></div>`}</div></div>`}
function renderGrades(){const rows=state.courses.map(c=>{const gp=courseGradePoints(c);const score=weightedCourseScore(c.id);return `<tr><td>${esc(c.name)}</td><td>${Number(c.credits)}</td><td><input class="inline-input" id="grade_${c.id}" value="${esc(c.grade||'')}" placeholder="A-"></td><td><input class="inline-input" id="gp_${c.id}" type="number" step="0.01" value="${c.gradePoint??''}" placeholder="auto"></td><td>${gp==null?'—':gp.toFixed(2)}</td><td>${score?score.score.toFixed(2)+'%':'—'}</td><td>${btn('Save',`saveGrade('${c.id}')`,'btn small')}${btn('Audit',`openCalculationAudit('${c.id}')`,'btn small')}</td></tr>`}).join('');const s= currentSemester(),sg=s?semesterGPA(s.id):null,all=cgpa();return pageHead('Academic','Grades & GPA','One authoritative calculation engine. Blank values are never treated as zero.',btn('＋ Assessment','openAssessmentModal()','btn primary'))+`<div class="stat-grid"><div class="card stat"><div class="stat-label">Current GPA</div><div class="stat-value">${sg==null?'—':sg.toFixed(2)}</div><div class="stat-foot">${s?esc(s.name):'No active semester'}</div></div><div class="card stat"><div class="stat-label">CGPA</div><div class="stat-value">${all==null?'—':all.toFixed(2)}</div><div class="stat-foot">All valid GPA-counted courses</div></div><div class="card stat"><div class="stat-label">Courses</div><div class="stat-value">${state.courses.length}</div><div class="stat-foot">Grade records</div></div><div class="card stat"><div class="stat-label">Assessments</div><div class="stat-value">${state.assessments.length}</div><div class="stat-foot">Raw marks saved</div></div></div><div class="section-head"><div class="section-title">Course grades</div><div class="section-note">Edit grade + grade points explicitly</div></div><div class="table-wrap"><table><thead><tr><th>Course</th><th>Cr</th><th>Official grade</th><th>Grade point</th><th>Used GP</th><th>Weighted score</th><th></th></tr></thead><tbody>${rows||`<tr><td colspan="7">No courses yet.</td></tr>`}</tbody></table></div><div class="section-head"><div class="section-title">Assessment records</div>${btn('＋ Add Assessment','openAssessmentModal()','btn small')}</div><div class="card"><div class="list">${state.assessments.slice(0,30).map(a=>`<div class="item"><div class="item-left"><div class="item-icon">⌁</div><div class="item-main"><div class="item-title">${esc(a.name)}</div><div class="item-sub">${esc(courseById(a.courseId)?.name||'Course')} · ${esc(a.type)} · ${a.obtained===''?'Pending':Number(a.obtained)+'/'+Number(a.max)} · ${Number(a.weight||0)}%</div></div></div><div class="item-right">${btn('Edit',`openAssessmentModal('${a.id}')`,'btn small')}</div></div>`).join('')||`<div class="empty"><h4>No assessments</h4><p>Add quizzes, assignments, labs, midterms and finals.</p></div>`}</div></div>`}
function renderAttendance(){const rows=state.courses.map(c=>{const a=attendanceStats(c.id);return `<div class="item"><div class="item-left"><div class="item-icon">◫</div><div class="item-main"><div class="item-title">${esc(c.name)}</div><div class="item-sub">${a.held} held · ${a.present} present · ${a.absent} absent · missing records are not counted</div></div></div><div class="item-right"><span class="pill ${a.percent!==null&&a.percent<75?'danger':'success'}">${a.percent==null?'—':a.percent.toFixed(1)+'%'}</span></div></div>`}).join('');return pageHead('Academic','Attendance','Record actual class attendance. Cancelled/excused and missing records are handled separately.',btn('＋ Attendance','openAttendanceModal()','btn primary'))+`<div class="card"><div class="list">${rows||`<div class="empty"><h4>No courses yet</h4><p>Create courses before recording attendance.</p></div>`}</div></div><div class="section-head"><div class="section-title">Recent records</div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Course</th><th>Status</th><th>Type</th><th></th></tr></thead><tbody>${state.attendance.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,50).map(a=>`<tr><td>${fmtDate(a.date)}</td><td>${esc(courseById(a.courseId)?.name||'—')}</td><td>${esc(a.status)}</td><td>${esc(a.type||'')}</td><td>${btn('Edit',`openAttendanceModal('${a.id}')`,'btn small')}</td></tr>`).join('')||`<tr><td colspan="5">No attendance records.</td></tr>`}</tbody></table></div></div>`}
function renderTasks(){const tasks=state.tasks.slice().sort((a,b)=>(a.status==='completed')-(b.status==='completed')||(a.dueDate+a.dueTime).localeCompare(b.dueDate+b.dueTime));return pageHead('Productivity','Tasks & Deadlines','One planner for assignments, projects, homework and personal tasks.',btn('＋ Task','openTaskModal()','btn primary'))+`<div class="stat-grid"><div class="card stat"><div class="stat-label">Open</div><div class="stat-value">${tasks.filter(t=>!['completed','cancelled'].includes(t.status)).length}</div></div><div class="card stat"><div class="stat-label">Due today</div><div class="stat-value">${tasks.filter(t=>t.dueDate===today()&&t.status!=='completed').length}</div></div><div class="card stat"><div class="stat-label">Overdue</div><div class="stat-value danger-text">${tasks.filter(t=>t.status!=='completed'&&t.status!=='cancelled'&&t.dueDate<today()).length}</div></div><div class="card stat"><div class="stat-label">Completed</div><div class="stat-value">${tasks.filter(t=>t.status==='completed').length}</div></div></div><div class="section-head"><div class="section-title">All tasks</div><div class="section-note">Deadline order</div></div><div class="card"><div class="list">${tasks.map(t=>`<div class="item"><div class="item-left"><div class="item-icon">${t.status==='completed'?'✓':'✓'}</div><div class="item-main"><div class="item-title">${esc(t.title)}</div><div class="item-sub">${esc(courseById(t.courseId)?.name||'Personal')} · ${fmtDate(t.dueDate)} ${esc(t.dueTime||'')}</div></div></div><div class="item-right"><span class="pill ${t.dueDate<today()&&t.status!=='completed'?'danger':t.priority==='high'||t.priority==='critical'?'warn':''}">${esc(t.status)}</span>${btn('Edit',`openTaskModal('${t.id}')`,'btn small')}</div></div>`).join('')||`<div class="empty"><h4>No tasks</h4><p>Your planner is clear.</p></div>`}</div></div>`}
function renderCalendar(){const d=new Date(),y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1),start=(first.getDay()-state.settings.weekStart+7)%7,days=new Date(y,m+1,0).getDate(),cells=[];for(let i=0;i<start;i++)cells.push(`<div class="cal-day other"></div>`);for(let day=1;day<=days;day++){const date=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,todayFlag=date===today();const items=[];state.tasks.filter(t=>t.dueDate===date).slice(0,3).forEach(t=>items.push(`<div class="cal-evt task">✓ ${esc(t.title)}</div>`));state.assessments.filter(a=>a.date===date).slice(0,3).forEach(a=>items.push(`<div class="cal-evt exam">⌁ ${esc(a.name)}</div>`));state.events.filter(e=>e.date===date).slice(0,3).forEach(e=>items.push(`<div class="cal-evt personal">□ ${esc(e.title)}</div>`));cells.push(`<div class="cal-day ${todayFlag?'today':''}"><div class="cal-num">${day}</div>${items.join('')}</div>`)}return pageHead('Planner','Calendar','One calendar view over tasks, assessments and personal events.',btn('＋ Event','openEventModal()','btn primary'))+`<div class="card"><div class="split"><div><div class="section-title">${d.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</div><div class="muted tiny">The calendar displays source records; it does not duplicate them.</div></div></div><div class="calendar" style="margin-top:14px">${DAY_SHORT.map(x=>`<div class="cal-head">${x}</div>`).join('')}${cells.join('')}</div></div>`}
function renderStudy(){const mins=state.studySessions.reduce((n,s)=>n+Number(s.minutes||0),0);return pageHead('Productivity','Study Tracker','Record actual study time, compare it with plans and keep a searchable history.',btn('＋ Study Session','openStudyModal()','btn primary'))+`<div class="stat-grid"><div class="card stat"><div class="stat-label">Total study</div><div class="stat-value">${(mins/60).toFixed(1)}h</div></div><div class="card stat"><div class="stat-label">Sessions</div><div class="stat-value">${state.studySessions.length}</div></div><div class="card stat"><div class="stat-label">Today</div><div class="stat-value">${(state.studySessions.filter(s=>s.date===today()).reduce((n,s)=>n+Number(s.minutes||0),0)/60).toFixed(1)}h</div></div><div class="card stat"><div class="stat-label">This week</div><div class="stat-value">${(state.studySessions.filter(s=>{const d=new Date(s.date+'T00:00:00');const now=new Date();const monday=new Date(now);monday.setDate(now.getDate()-((now.getDay()+6)%7));return d>=new Date(monday.toDateString());}).reduce((n,s)=>n+Number(s.minutes||0),0)/60).toFixed(1)}h</div></div></div><div class="section-head"><div class="section-title">Recent sessions</div></div><div class="card"><div class="list">${state.studySessions.slice(0,40).map(s=>`<div class="item"><div class="item-left"><div class="item-icon">◉</div><div class="item-main"><div class="item-title">${esc(courseById(s.courseId)?.name||'General')} ${s.topic?'· '+esc(s.topic):''}</div><div class="item-sub">${fmtDate(s.date)} · ${Number(s.minutes)} min ${s.note?'· '+esc(s.note):''}</div></div></div></div>`).join('')||`<div class="empty"><h4>No study sessions</h4><p>Start logging your actual study time.</p></div>`}</div></div>`}
function renderGoals(){return pageHead('Productivity','Goals','Targets stay separate from actual academic results.',btn('＋ Goal','openGoalModal()','btn primary'))+`<div class="grid g3">${state.goals.map(g=>`<div class="card hover"><div class="eyebrow">${esc(g.status||'active')}</div><div class="item-title" style="font-size:14px;margin-top:7px">${esc(g.title)}</div><div class="item-sub" style="margin-top:5px">${esc(g.description||'')}</div><div class="progress" style="margin-top:12px"><i style="width:${Math.max(0,Math.min(100,Number(g.progress)||0))}%"></i></div><div class="split" style="margin-top:7px"><span class="tiny muted">${Number(g.progress||0).toFixed(0)}%</span>${btn('Edit',`openGoalModal('${g.id}')`,'btn small')}</div></div>`).join('')||`<div class="empty"><h4>No goals yet</h4><p>Create a semester, course or personal target.</p></div>`}</div>`}
function openGoalModal(id=''){const g=id?state.goals.find(x=>x.id===id):{title:'',description:'',progress:0,status:'active'};modal(id?'Edit Goal':'Add Goal','Keep targets separate from official calculations.',`<div class="form-grid"><div class="field full"><label>Title</label><input id="f_gt" value="${esc(g.title)}" placeholder="Semester GPA ≥ 3.5"></div><div class="field full"><label>Description</label><textarea id="f_gd">${esc(g.description||'')}</textarea></div><div class="field"><label>Progress %</label><input id="f_gp" type="number" min="0" max="100" value="${Number(g.progress||0)}"></div><div class="field"><label>Status</label><select id="f_gs"><option value="active" ${g.status==='active'?'selected':''}>Active</option><option value="paused" ${g.status==='paused'?'selected':''}>Paused</option><option value="completed" ${g.status==='completed'?'selected':''}>Completed</option></select></div></div>`,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveGoal('${id}')">Save Goal</button>`)}
function saveGoal(id){const title=val('f_gt').trim();if(!title)return userError('Goal title required','A goal needs a name to track it.','Enter a clear target.');let g=id?state.goals.find(x=>x.id===id):{id:uid('goal')};Object.assign(g,{title,description:val('f_gd'),progress:Math.max(0,Math.min(100,Number(val('f_gp'))||0)),status:val('f_gs')});if(!id)state.goals.push(g);log(`${id?'Edited':'Created'} goal: ${title}`);closeModal();refresh();toast('Goal saved','Progress is stored locally.');}
function renderNotes(){return pageHead('Knowledge','Notes','Local notes connected to courses and searchable from the global command bar.',btn('＋ Note','openNoteModal()','btn primary'))+`<div class="grid g3">${state.notes.map(n=>`<div class="card hover clickable" onclick="openNoteModal('${n.id}')"><div class="eyebrow">${esc(courseById(n.courseId)?.name||'General')}</div><div class="item-title" style="font-size:14px;margin-top:8px">${esc(n.title)}</div><div class="item-sub" style="white-space:normal;line-height:1.55;margin-top:5px">${esc((n.content||'').slice(0,180))}</div><div class="chip-row" style="margin-top:10px">${(n.tags||'').split(/\s+/).filter(Boolean).slice(0,4).map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div></div>`).join('')||`<div class="empty"><h4>No notes</h4><p>Create quick lecture notes, concepts, formulas and revision material.</p></div>`}</div>`}
function resourceRow(r){return `<div class="item clickable" onclick="openResourceModal('${r.id}')"><div class="item-left"><div class="item-icon">${esc(r.icon||'🌐')}</div><div class="item-main"><div class="item-title">${esc(r.name||r.url)}</div><div class="item-sub">${esc(r.type||'Website')} · ${esc(r.url)}</div></div></div><div class="item-right"><span class="pill">${r.courseIds?.length||0} links</span></div></div>`}
function renderResources(){return pageHead('Knowledge','Resources','URL-first library with offline recognition, custom rules and editable labels.',btn('＋ URL','openResourceModal()','btn primary'),btn('＋ Rule','openCustomRuleModal()','btn'))+`<div class="stat-grid"><div class="card stat"><div class="stat-label">Saved URLs</div><div class="stat-value">${state.resources.length}</div><div class="stat-foot">Local resources</div></div><div class="card stat"><div class="stat-label">Custom rules</div><div class="stat-value">${state.settings.customUrlRules?.length||0}</div><div class="stat-foot">User-defined recognition</div></div><div class="card stat"><div class="stat-label">Known services</div><div class="stat-value">${URL_RULES.length}</div><div class="stat-foot">Built-in offline recognizers</div></div><div class="card stat"><div class="stat-label">Unknown websites</div><div class="stat-value">${state.resources.filter(r=>r.name===safeHost(r.url)&&r.icon==='🌐').length}</div><div class="stat-foot">Generic globe fallback</div></div></div><div class="section-head"><div class="section-title">Resource library</div><div class="section-note">Everything editable</div></div><div class="card"><div class="list">${state.resources.map(resourceRow).join('')||`<div class="empty"><h4>No resources</h4><p>Paste any URL. GitHub, YouTube, Google services and many others are recognized offline.</p></div>`}</div></div>`}
function safeHost(url){try{return new URL(url).hostname.replace(/^www\./,'')}catch{return url}}
function renderAnalytics(){const g=state.semesters.map(s=>semesterGPA(s.id)).filter(x=>x!==null);const max=Math.max(4,...state.gradingProfiles.flatMap(g=>g.scale.map(x=>Number(x[1]))));return pageHead('Insights','Analytics','Statistics are derived from stored records only; missing data is never fabricated.',btn('Refresh','refresh()','btn'))+`<div class="stat-grid"><div class="card stat"><div class="stat-label">CGPA</div><div class="stat-value">${cgpa()==null?'—':cgpa().toFixed(2)}</div></div><div class="card stat"><div class="stat-label">Study hours</div><div class="stat-value">${(state.studySessions.reduce((n,s)=>n+Number(s.minutes||0),0)/60).toFixed(1)}</div></div><div class="card stat"><div class="stat-label">Task completion</div><div class="stat-value">${taskCompletion().toFixed(0)}%</div></div><div class="card stat"><div class="stat-label">Average attendance</div><div class="stat-value">${avgAttendance()==null?'—':avgAttendance().toFixed(1)+'%'}</div></div></div><div class="grid g2" style="margin-top:13px"><div class="card"><div class="section-title">Semester GPA trend</div><canvas id="gpaCanvas" class="sparkline" width="800" height="160"></canvas><div class="chip-row" style="margin-top:8px">${state.semesters.map(s=>`<span class="chip">${esc(s.name)}: ${semesterGPA(s.id)==null?'—':semesterGPA(s.id).toFixed(2)}</span>`).join('')}</div></div><div class="card"><div class="section-title">Academic workload</div><div class="list" style="margin-top:10px">${state.courses.slice(0,8).map(c=>{const t=state.tasks.filter(x=>x.courseId===c.id&&x.status!=='completed').length;const a=attendanceStats(c.id).percent;return `<div class="item"><div class="item-main"><div class="item-title">${esc(c.name)}</div><div class="item-sub">${t} open tasks · attendance ${a==null?'—':a.toFixed(1)+'%'}</div></div></div>`}).join('')||`<div class="empty"><h4>Not enough data yet</h4><p>Add courses, tasks and attendance to build your analytics.</p></div>`}</div></div></div><div class="alert info" style="margin-top:13px">Analytics are observational. They do not invent grades, predict outcomes without explicit inputs, or replace official university results.</div>`;
}
function taskCompletion(){const a=state.tasks.filter(t=>t.status!=='cancelled');return a.length?state.tasks.filter(t=>t.status==='completed').length/a.length*100:0}
function avgAttendance(){const xs=state.courses.map(c=>attendanceStats(c.id).percent).filter(x=>x!=null);return xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null}
function drawGPA(){const c=document.getElementById('gpaCanvas');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const vals=state.semesters.map(s=>semesterGPA(s.id));const good=vals.filter(v=>v!==null);if(!good.length){ctx.fillStyle='#7585a0';ctx.font='12px system-ui';ctx.fillText('Add official grades to see the trend.',20,70);return;}const max=Math.max(4,...good),min=0;ctx.strokeStyle='rgba(255,255,255,.08)';for(let i=0;i<5;i++){const y=15+i*(h-30)/4;ctx.beginPath();ctx.moveTo(20,y);ctx.lineTo(w-20,y);ctx.stroke();}ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();ctx.lineWidth=4;ctx.beginPath();vals.forEach((v,i)=>{if(v===null)return;const x=30+(w-60)*(i/Math.max(vals.length-1,1));const y=h-18-(v/max)*(h-36);i===0?ctx.moveTo(x,y):ctx.lineTo(x,y);});ctx.stroke();}
function renderSettings(){const effects=state.settings.effects;return pageHead('System','Settings','Control themes, effects, personalization, notifications, URL recognition and data protection.',btn('Run Tour','startTour(true)','btn primary'))+`<div class="grid g2"><div class="card"><div class="section-title">Visual themes</div><div class="form-help" style="margin:6px 0 11px">Premium themes change the entire visual language without touching your data.</div><div class="theme-grid">${THEMES.map(t=>`<button class="theme-card ${state.settings.theme===t[0]?'selected':''}" onclick="setTheme('${t[0]}')"><span class="theme-dot sw-${t[0]}"></span><strong>${t[1]}</strong><small>${t[2]}</small></button>`).join('')}</div></div><div class="card"><div class="section-title">Effects</div><div class="list" style="margin-top:8px">${['ambient','glass','motion','grid','cursor','ripple','particles'].map(k=>`<div class="item"><div class="item-main"><div class="item-title">${k[0].toUpperCase()+k.slice(1)}</div><div class="item-sub">${effectDesc(k)}</div></div><label class="switch"><input type="checkbox" ${effects[k]!==false?'checked':''} onchange="setEffect('${k}',this.checked)"><span></span></label></div>`).join('')}</div></div></div><div class="grid g2" style="margin-top:13px"><div class="card"><div class="section-title">Time & personalization</div><div class="list" style="margin-top:8px"><div class="item"><div class="item-main"><div class="item-title">Display name</div><div class="item-sub">${esc(state.profile.name||'Student')}</div></div>${btn('Edit',`openAcademicModal()`,'btn small')}</div><div class="item"><div class="item-main"><div class="item-title">12 / 24-hour clock</div></div><label class="switch"><input type="checkbox" ${state.settings.clock24?'checked':''} onchange="state.settings.clock24=this.checked;persist();refresh()"><span></span></label></div><div class="item"><div class="item-main"><div class="item-title">Show greeting</div></div><label class="switch"><input type="checkbox" ${state.settings.showGreeting?'checked':''} onchange="state.settings.showGreeting=this.checked;persist();refresh()"><span></span></label></div><div class="item"><div class="item-main"><div class="item-title">Accent color</div></div><input type="color" value="${esc(state.settings.accent)}" onchange="setAccent(this.value)" style="height:33px;width:44px;padding:3px;border:1px solid var(--border);border-radius:9px;background:transparent"></div></div></div><div class="card"><div class="section-title">Notifications</div><div class="list" style="margin-top:8px"><div class="item"><div class="item-main"><div class="item-title">Browser notifications</div><div class="item-sub">In-app reminders always remain available.</div></div>${btn('Request',`requestNotifications()`,'btn small')}</div>${androidAvailable()?`<div class="item"><div class="item-main"><div class="item-title">Android notifications</div><div class="item-sub">Use Android's native notification permission and settings.</div></div><div class="row-actions">${btn('Enable','MaoozAndroid.requestNotifications()','btn small primary')}${btn('System settings','MaoozAndroid.openNotificationSettings()','btn small')}${btn('Test','MaoozAndroid.testNotification()','btn small')}</div></div><div class="item"><div class="item-main"><div class="item-title">Precise class reminders</div><div class="item-sub" data-exact-alarm-status>Checking Android exact-alarm access…</div></div>${btn('Configure','MaoozAndroid.openExactAlarmSettings()','btn small')}</div>`:''}<div class="item"><div class="item-main"><div class="item-title">Notification engine</div><div class="item-sub">${state.settings.notifications?'Enabled':'Disabled'}</div></div><label class="switch"><input type="checkbox" ${state.settings.notifications?'checked':''} onchange="state.settings.notifications=this.checked;persist();refresh()"><span></span></label></div><div class="item"><div class="item-main"><div class="item-title">Quiet hours</div><div class="item-sub">${state.settings.quietStart}–${state.settings.quietEnd}</div></div><label class="switch"><input type="checkbox" ${state.settings.quietHours?'checked':''} onchange="state.settings.quietHours=this.checked;persist();refresh()"><span></span></label></div></div></div></div><div class="grid g2" style="margin-top:13px"><div class="card"><div class="section-title">Data & backup</div><div class="row-actions" style="margin-top:10px">${btn('Export Full Backup','backupExport()','btn primary')}${btn('Import Backup','backupImport()','btn')}${btn('Test Notification','pushNotification(\'Test notification\',\'MaoozOS reminder engine is working locally.\')','btn')}${androidAvailable()?btn('Test in 1 min','scheduleTestReminder()','btn'):''}</div><div class="alert info" style="margin-top:12px">All records and settings are stored locally. Export backups before major changes or browser resets.</div></div><div class="card"><div class="section-title">URL recognition</div><div class="muted tiny" style="margin-top:6px">${URL_RULES.length} built-in service patterns. Your overrides always win.</div><div class="row-actions" style="margin-top:10px">${btn('＋ Custom Rule','openCustomRuleModal()','btn small')}${btn('Clear Custom Rules','clearCustomRules()','btn small danger')}</div></div></div>`}
function effectDesc(k){return ({ambient:'Animated background glow',glass:'Frosted panel depth',motion:'Hover and page transitions',grid:'Ambient background grid',cursor:'Cursor-following accent glow',ripple:'Click ripple interaction',particles:'Floating background particles'})[k]||''}
function setTheme(t){if(!THEMES.some(x=>x[0]===t))return userError('Theme unavailable','The selected theme is not installed.','Choose one shown in Settings.');state.settings.theme=t;persist();applyTheme();renderCurrent();toast('Theme applied',t+' is now active.');}
function setAccent(c){if(!/^#[0-9a-f]{6}$/i.test(c))return userError('Accent color invalid','The color picker returned an unexpected value.','Choose another color.');state.settings.accent=c;persist();applyTheme();renderCurrent();}
function setEffect(k,v){state.settings.effects[k]=v;persist();applyTheme();renderCurrent();}
function clearCustomRules(){if(!state.settings.customUrlRules?.length)return toast('No custom rules','There are no user rules to remove.','warn');if(!confirm('Remove all custom URL recognition rules? Existing resources are not changed.'))return;state.settings.customUrlRules=[];persist();refresh();toast('Custom rules cleared','Existing resources keep their saved labels.');}
function renderAbout(){return pageHead('MaoozOS','About','Personal Academic & Productivity Operating System',btn('Run Tour','startTour(true)','btn primary'))+`<div class="card" style="text-align:center;padding:50px 18px"><div class="brand-mark" style="margin:0 auto 14px">M</div><div style="font-size:34px;font-weight:900;letter-spacing:-.06em">MaoozOS</div><div class="muted" style="margin-top:6px">Local-first · private · customizable · mobile-ready architecture</div><div class="pill" style="margin-top:13px">v${VERSION}</div><div style="margin-top:24px;font-size:12px;color:#9baac2">Developed by Muhammad Maooz</div><div class="alert info" style="margin:24px auto 0;max-width:680px">No external scripts or fonts are required by the app itself. Your records and settings are saved locally in the browser.</div></div>`}
function backupExport(){try{persist();const payload={app:'MaoozOS',format:'maoozos-full-backup',schema:1,version:VERSION,platform:androidAvailable()?'android':'web',exportedAt:new Date().toISOString(),data:state};const json=JSON.stringify(payload,null,2);if(androidAvailable()&&typeof MaoozAndroid.saveBackupFile==='function'){MaoozAndroid.saveBackupFile(json,`MaoozOS-full-backup-${today()}.json`);log('Opened native backup save dialog');return;}const blob=new Blob([json],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`MaoozOS-full-backup-${today()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);log('Exported full backup');toast('Backup exported','Transfer this file to the other device and import it there.');}catch(e){userError('Backup export failed',e.message||'MaoozOS could not create the backup file.','Your current data remains unchanged.');}}
function backupImport(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files&&input.files[0];if(!file)throw new Error('No backup file was selected.');const text=await file.text();if(!text.trim())throw new Error('The selected file is empty.');const obj=JSON.parse(text);if(!obj||obj.app!=='MaoozOS')throw new Error('This file is not a MaoozOS backup.');if(obj.format&&obj.format!=='maoozos-full-backup')throw new Error('This backup format is not supported.');const incoming=obj.data||obj;if(!incoming||typeof incoming!=='object'||!incoming.profile||!Array.isArray(incoming.courses)||!Array.isArray(incoming.semesters)||!Array.isArray(incoming.tasks)||!Array.isArray(incoming.notes)||!Array.isArray(incoming.resources))throw new Error('Backup structure is incomplete or corrupted.');const previous=JSON.stringify(state);const restored=mergeData(baseData(),incoming);state=restored;try{if(!persist())throw new Error('Local storage rejected the restored dataset.');const check=JSON.parse(localStorage.getItem(KEY));if(!check||!check.profile)throw new Error('Local storage rejected the restored dataset.');}catch(e){state=JSON.parse(previous);persist();throw new Error('The backup was not applied because local storage could not safely save the restored data.');}renderApp();applyTheme();toast('Backup restored','Your MaoozOS records and configuration were restored.','ok');log('Restored full backup');syncNativeReminders();}catch(e){userError('Backup could not be restored',e.message||'The file was not recognized.','Your previous local data was kept unchanged.');}};input.click();}
function openSearchPage(q){q=String(q||'').trim();if(!q)return;const results=searchAll(q);const body=results.length?'<div class="list">'+results.map(r=>'<div class="item"><div class="item-left"><div class="item-icon">'+esc(r.icon)+'</div><div class="item-main"><div class="item-title">'+esc(r.title)+'</div><div class="item-sub">'+esc(r.module)+' · '+esc(r.sub)+'</div></div></div></div>').join('')+'</div>':'<div class="empty"><h4>No matches</h4><p>Try another word or URL fragment.</p></div>';modal('Search results','Found '+results.length+' matching records.',body,'<button class="btn" onclick="closeModal()">Close</button>');}
function liveSearch(q){const box=document.getElementById('searchResults');if(!box)return;if(!q.trim()){box.classList.remove('open');box.innerHTML='';return;}const res=searchAll(q).slice(0,14);box.innerHTML=res.length?res.map((r,i)=>`<button class="result" onclick="closeSearchAndOpen('${esc(r.moduleId)}')"><div class="r-ico">${esc(r.icon)}</div><div class="r-main"><div class="r-title">${esc(r.title)}</div><div class="r-sub">${esc(r.module)} · ${esc(r.sub)}</div></div></button>`).join(''):`<div class="empty" style="margin:4px"><h4>No matches</h4><p>Try a course, class, task, URL, page name, semester or feature.</p></div>`;box.classList.add('open')}
function closeSearchAndOpen(moduleId){document.getElementById('searchResults')?.classList.remove('open');if(moduleId)showPage(moduleId);}
function searchAll(q){const x=String(q||'').trim().toLowerCase();const out=[];const push=(moduleId,icon,module,title,sub,action)=>out.push({moduleId,icon,module,title,sub,action});if(!x)return out;const pages=[['dashboard','⌂','Dashboard','Command center, classes, deadlines and next class'],['academic','🎓','Academic Profile','University, degree, batch, grading and academic settings'],['semesters','▤','Semesters','Semester history, GPA snapshots and academic records'],['courses','📚','Courses','Course hub with credits, grades, tasks, attendance and resources'],['timetable','🗓','Timetable','Classes, schedule, rooms, instructors and reminders'],['grades','∑','Grades & GPA','Assessments, grading profiles, GPA, CGPA and what-if calculations'],['attendance','◫','Attendance','Attendance records, thresholds and projections'],['tasks','✓','Tasks','Assignments, deadlines, projects and subtasks'],['calendar','□','Calendar','Classes, deadlines, tasks, exams and events'],['study','◉','Study','Study planning, sessions and focus tracking'],['goals','◎','Goals','Academic and personal targets'],['notes','✦','Notes','Knowledge base, topics and linked notes'],['resources','↗','Resources','URL library and automatic service recognition'],['analytics','◈','Analytics','Academic and productivity statistics'],['settings','⚙','Settings','Themes, effects, notifications, backups and customization'],['about','ⓘ','About','MaoozOS information and developer credit']];pages.forEach(r=>{if((r[2]+' '+r[3]).toLowerCase().includes(x))push(r[0],r[1],'App',r[2],r[3])});state.profile&&(['name','university','campus','department','degree','batch','rollNo','advisor'].some(k=>String(state.profile[k]||'').toLowerCase().includes(x))&&push('academic','🎓','Academic Profile',state.profile.university||state.profile.name||'Academic Profile','Profile information'));state.courses.forEach(c=>{if([c.name,c.code,c.instructor,c.section].join(' ').toLowerCase().includes(x))push('courses',c.icon||'◈','Course',c.name,`${c.code||'No code'} · ${Number(c.credits)} credits`)});state.semesters.forEach(s=>{if([s.name,s.academicYear,s.status].join(' ').toLowerCase().includes(x))push('semesters','▤','Semester',s.name,`${s.academicYear||''} · ${s.status}`)});state.tasks.forEach(t=>{if([t.title,t.type,t.description,t.tags].join(' ').toLowerCase().includes(x))push('tasks','✓','Task',t.title,`${t.type} · ${fmtDate(t.dueDate)}`)});state.notes.forEach(n=>{if([n.title,n.content,n.tags,n.topic].join(' ').toLowerCase().includes(x))push('notes','✦','Note',n.title,`${courseById(n.courseId)?.name||'General'} · ${n.topic||''}`)});state.resources.forEach(r=>{if([r.name,r.url,r.type,r.tags].join(' ').toLowerCase().includes(x))push('resources',r.icon||'🌐','Resource',r.name,`${r.type||'Website'} · ${r.url}`)});state.assessments.forEach(a=>{if([a.name,a.type,a.description].join(' ').toLowerCase().includes(x))push('grades','⌁','Assessment',a.name,`${courseById(a.courseId)?.name||''} · ${fmtDate(a.date)}`)});state.timetable.forEach(t=>{if([courseById(t.courseId)?.name,t.room,t.instructor,t.type,DAYS[Number(t.day)]].join(' ').toLowerCase().includes(x))push('timetable','🗓','Class',courseById(t.courseId)?.name||'Class',`${DAYS[Number(t.day)]} · ${fmtTime(t.start)}–${fmtTime(t.end)}`)});return out;}
function startTour(force=false){let i=0;const steps=[['Welcome to MaoozOS','This is your personal academic operating system. Your data is saved locally, and the tour can be replayed anytime.','app'],['Dashboard first','Classes and deadlines are deliberately at the top because they are the information you need most often.','page-dashboard'],['Timetable','Add every class once. The same class drives the weekly timetable, Today view and reminders.','page-timetable'],['Grades & calculations','Enter official grades and valid credits. Blank values never become zero, and GPA/CGPA comes from one central calculation engine.','page-grades'],['Attendance','Record actual attendance. Missing records are not treated as absences, and cancelled/excused sessions are handled separately.','page-attendance'],['Tasks & deadlines','Assignments, projects and personal tasks live here and automatically appear on Dashboard and Calendar.','page-tasks'],['Notes & URLs','Paste URLs anywhere. Common services are recognized offline, unknown links use a globe, and every label is editable.','page-resources'],['Themes & effects','Choose from twelve visual themes and control glow, blur, motion, grid, cursor and particles from Settings.','page-settings'],['Backup','Export backups before browser resets or major changes. Restore is validation-checked so bad files do not silently replace your data.','page-settings'],['Finish','You are ready. Run this tour again from Settings or the sidebar whenever you need it.','page-dashboard']];const backdrop=document.getElementById('tourBackdrop'),card=document.getElementById('tourCard'),focus=document.getElementById('tourFocus');backdrop.classList.add('open');card.classList.remove('hidden');focus.classList.remove('hidden');function clamp(v,min,max){return Math.max(min,Math.min(v,max));}function position(){const s=steps[i],target=document.getElementById(s[2]);card.style.transform='none';if(!target){card.style.left='16px';card.style.top='16px';return;}const r=target.getBoundingClientRect();const fw=Math.min(r.width+10,window.innerWidth-8),fh=Math.min(r.height+10,window.innerHeight-8);focus.style.left=clamp(r.left-5,4,window.innerWidth-fw-4)+'px';focus.style.top=clamp(r.top-5,4,window.innerHeight-fh-4)+'px';focus.style.width=fw+'px';focus.style.height=fh+'px';const gap=16,margin=16;const cw=Math.min(card.offsetWidth||420,window.innerWidth-32);const ch=Math.min(card.offsetHeight||260,window.innerHeight-32);const below=r.bottom+gap,above=r.top-ch-gap;let top=below<=window.innerHeight-margin-ch?below:(above>=margin?above:clamp((window.innerHeight-ch)/2,margin,window.innerHeight-ch-margin));let left=clamp(r.left+20,margin,window.innerWidth-cw-margin);card.style.left=Math.round(left)+'px';card.style.top=Math.round(top)+'px';}function render(){const s=steps[i];document.getElementById('tourCard').innerHTML=`<div class="eyebrow">MAOOZOS · GUIDED TOUR ${i+1}/${steps.length}</div><h3>${esc(s[0])}</h3><p>${esc(s[1])}</p><div class="tour-progress">${steps.map((_,n)=>`<i class="${n<=i?'on':''}"></i>`).join('')}</div><div class="tour-actions">${i?btn('Back','tourPrev()','btn'):''}${btn('Skip','closeTour()','btn')}${btn(i===steps.length-1?'Finish':'Next','tourNext()','btn primary')}</div>`;requestAnimationFrame(position);}window.tourNext=()=>{if(i===steps.length-1){state.tourDone=true;persist();closeTour();toast('Tour complete','You can replay it from Settings or the sidebar.');return;}i++;render();};window.tourPrev=()=>{i=Math.max(0,i-1);render();};window.closeTour=()=>{backdrop.classList.remove('open');card.classList.add('hidden');focus.classList.add('hidden');};window.addEventListener('resize',position,{passive:true});render();}

function ensureEffects(){if(window.MaoozAndroid)return;
  if(document.getElementById('particleLayer'))return;
  const layer=document.createElement('div');layer.id='particleLayer';layer.style.cssText='position:fixed;inset:0;pointer-events:none;z-index:-2;overflow:hidden;';document.body.appendChild(layer);
  for(let i=0;i<26;i++){const s=document.createElement('span');const size=2+Math.random()*3;s.style.cssText=`position:absolute;width:${size}px;height:${size}px;border-radius:50%;left:${Math.random()*100}%;top:${Math.random()*100}%;background:${state.settings.accent};opacity:${0.08+Math.random()*0.15};filter:blur(${Math.random()*1.5}px);animation:particleFloat ${8+Math.random()*14}s linear infinite;animation-delay:-${Math.random()*20}s`;layer.appendChild(s)}
}
function applyExtraEffects(){
 ensureEffects();const layer=document.getElementById('particleLayer');if(layer)layer.style.display=state.settings.effects?.particles===false?'none':'block';
 document.body.onmousemove=null;
 if(state.settings.effects?.cursor!==false){document.body.onmousemove=e=>{document.documentElement.style.setProperty('--mx',e.clientX+'px');document.documentElement.style.setProperty('--my',e.clientY+'px')}}
}
const effectStyle=document.createElement('style');effectStyle.textContent='@keyframes particleFloat{0%{transform:translate3d(0,0,0);opacity:.05}50%{transform:translate3d(20px,-35px,0);opacity:.22}100%{transform:translate3d(-15px,-80px,0);opacity:.03}}body:before{transform-origin:var(--mx,50%) var(--my,50%)}';document.head.appendChild(effectStyle);
const oldApplyTheme=applyTheme;applyTheme=function(){oldApplyTheme();applyExtraEffects()};
const oldRenderCurrent=renderCurrent;renderCurrent=function(){oldRenderCurrent();if(current==='analytics')setTimeout(drawGPA,0)};
window.addEventListener('error',e=>{try{toast('MaoozOS recovered from an error','The app stayed open. Your saved data was not intentionally changed.','err')}catch(_){}});window.addEventListener('unhandledrejection',e=>{try{toast('MaoozOS recovered from a background error','Try the action again. Your saved data was not intentionally changed.','err')}catch(_){}});
boot();
